files.Caddyfile:
{
	auto_https off
	admin off
	frankenphp {
		worker {
			file /app/frankenphp/worker.php
			num 100
			env BLOG_DSN "pgsql:host=127.0.0.1;port=55440;dbname=bench;user=postgres;password=bench"
			env BLOG_STMT_CACHE "0"
			env BLOG_EMULATE_PREPARES "0"
			env BLOG_UPSTREAM "http://127.0.0.1:9090/wait?ms=1000"
		}
	}
}
http://127.0.0.1:8083 {
	bind 127.0.0.1
	root * /app/frankenphp
	rewrite * /worker.php
	php
}

